const ELEMENT_PROP_KEYS = new Set(["theme","startLabel","goalLabel","cols","rows","floodStep","trace","accent","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  startLabel: "Start",
  goalLabel: "Goal",
  cols: 17,
  rows: 9,
  floodStep: 1.45,
  trace: 32,
  accent: "#3B5BFD",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type PathSearchElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PathSearchBase>;

const PathSearchInner = forwardRef<
  HTMLDivElement,
  PathSearchElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PathSearch>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PathSearchBase
          {...(componentProps as unknown as ComponentProps<typeof PathSearchBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PathSearch = Interactive.withSchema({
  Component: PathSearchInner,
  componentName: "<PathSearch>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
